            dt = datetime.datetime.strptime(date_str, expression)
            if meridiem:
                if meridiem.group(1).upper() == 'PM' and dt.hour < 12:
                    dt += datetime.timedelta(hours=12)
                elif meridiem.group(1).upper() == 'AM' and dt.hour == 12:
                    dt -= datetime.timedelta(hours=12)
            return calendar.timegm((dt - timezone).timetuple())
        except ValueError:
            pass

    normalized = re.sub(r'(?i)(\d+)(?:st|nd|rd|th)\b', r'\1', date_str)
    normalized = re.sub(r'(?i)(\d)(AM|PM)\b', r'\1 \2', normalized)
    timetuple = email.utils.parsedate_tz(normalized)
    if timetuple:
        dt = datetime.datetime(*timetuple[:6]) - timezone
        return calendar.timegm(dt.timetuple())
    return None

